items
      .filter((item) => {
        const hasTags = item.tags && item.tags.length > 0;
        if (!hasTags && !showUntagged) return false;
        if (hasTags && !showTagged) return false;

        if (!item.createdTime && !showWithoutTimestamp) return false;

        if (enableDateFilter) {
          const created = item.createdTime ? parseDate(item.createdTime) : null;
          const createdDay = created ? created.toISOString().split('T')[0] : null;
          if (createdDay) {
            if (dateFilterFrom && createdDay < dateFilterFrom) return false;
            if (dateFilterTo && createdDay > dateFilterTo) return false;
          } else if (dateFilterExcludesUndated) {
            return false;
          }
        }

        return true;
      })
      .sort

(() => {
          /* eslint-disable-next-line @next/next/no-img-element -- full-size remote
             images from Firebase Storage; the dev image optimizer stalls on them,
             consistent with the album grid which also uses a native <img>. */
          const img = (
            <img
              src={image.imageUrl}
              alt={image.fileName}
              className={`mx-auto h-auto max-h-[80vh] w-auto rounded-xl object-contain ${
                imageLoading ? 'hidden' : ''
              }`}
              onLoad={() => setImageLoading(false)}
              onError={() => {
                setImageLoading(false);
                setImageError(true);
              }}
            />
          );

          if (!isMobile) return img;

          // Mobile-only pinch-zoom (desktop stays plain). Keyed per image so
          // navigating resets the transform to fit.
          return (
            <TransformWrapper
              key={image.imageUrl}
              minScale={1}
              maxScale={4}
              doubleClick={{ mode: 'toggle' }}
              wheel={{ disabled: true }}
              panning={{ disabled: !zoomed }}
              onTransform={(_, state) => setZoomed(state.scale > 1.01)}
            >
              <TransformComponent
                wrapperStyle={{ width: '100%', touchAction: zoomed ? 'none' : 'pan-y' }}
                contentStyle={{ width: '100%' }}
              >
                {img}
              </TransformComponent>
            </TransformWrapper>
          );
        })

